export const ICON_NAMES = Object.keys(UI_ICONS) as IconName[]

export function icon(name: IconName, cls?: string): Html {
  return html`<svg class="i${cls ? ` ${cls}` : ""}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${new Html(UI_ICONS[name])}</svg>`
}

