export function vaultMark(cls?: string, variant: CoilVariant = "coil"): Html {
  const c = COILS[variant]
  return html`<svg class="mark${cls ? ` ${cls}` : ""}" viewBox="0 0 64 64" fill="none" aria-hidden="true"><path d="${c.line}" fill="none" stroke="currentColor" stroke-width="${c.stroke}" stroke-linecap="round" stroke-linejoin="round"/><g transform="${c.head}"><path d="${HEAD_PATH}" fill="currentColor"/><circle cx="4.6" cy="-1.1" r="0.85" fill="var(--bg, #fff)"/></g><circle cx="32" cy="32" r="${c.sun}" fill="var(--sun, currentColor)"/></svg>`
}
